const opponentLink=g=>{const label=g.opponent??g.opponent_name??'—',prefix=g.location==='Away'?'@ ':g.location==='Neutral'?'vs ':'';const slug=opponentPages[String(g.opponent_id)]||opponentNames[String(label).toLowerCase().trim()];return h(prefix)+(slug?'<a class="cbb-schedule-opponent" href="/cbb/teams/'+encodeURIComponent(slug)+'/">'+h(label)+'</a>':h(label));};
let archive,rankArchive={},recruitArchive={},conferenceResults={},tournamentResults={},awardResults={},marketArchive={},pregameArchive={},opponentMetrics={},draftHistory={},year='2027',phase='regular';
