 const totals=[['Record',done.length?record(done):'—'],['PPG',format(m.avgPoints)],['PPG Allowed',format(ratio(oppPoints,gp))],['Home',done.some(g=>g.location==='Home')?record(done.filter(g=>g.location==='Home')):'—'],['Away',done.some(g=>g.location==='Away')?record(done.filter(g=>g.location==='Away')):'—'],['Neutral',done.some(g=>g.location==='Neutral')?record(done.filter(g=>g.location==='Neutral')):'—'],['Games',done.length||'—']];
 const statTiles=(items,kind='snapshot')=>'<div class="cbb-archive-metrics cbb-'+kind+'-grid">'+items.map(([k,v,sub])=>'<article><strong>'+h(v)+'</strong><span>'+h(k)+'</span>'+(sub?'<small>'+h(sub)+'</small>':'')+'</article>').join('')+'</div>';
 const market=(g,type)=>{const x=type==='ats'?(g.ats??g.ats_result):(g.ou??g.ou_result);return ['W','L','P','O','U'].includes(x)?x:'—'};
